// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListBackends List the model backends. Secrets show their last 4 characters only (SDD §14.1).
	// (GET /admin/backends)
	ListBackends(w http.ResponseWriter, r *http.Request)
	// CreateBackend Add a model backend (REQ-100).
	// (POST /admin/backends)
	CreateBackend(w http.ResponseWriter, r *http.Request)
	// DeleteBackend Delete a backend that no role uses.
	// (DELETE /admin/backends/{backendId})
	DeleteBackend(w http.ResponseWriter, r *http.Request, backendId BackendId)
	// UpdateBackend Change a backend. Leave the secret out to keep the stored one.
	// (PUT /admin/backends/{backendId})
	UpdateBackend(w http.ResponseWriter, r *http.Request, backendId BackendId)
	// TestBackend Send one short call to a backend and model, to check the setup.
	// (POST /admin/backends/{backendId}/test)
	TestBackend(w http.ResponseWriter, r *http.Request, backendId BackendId)
	// GetBudget Get this month's token budget and use (REQ-104).
	// (GET /admin/budget)
	GetBudget(w http.ResponseWriter, r *http.Request)
	// SetBudget Set the monthly token limit. No limit means no budget.
	// (PUT /admin/budget)
	SetBudget(w http.ResponseWriter, r *http.Request)
	// DeleteGithubConnection Remove the GitHub token. The GitHub sources stop syncing.
	// (DELETE /admin/github)
	DeleteGithubConnection(w http.ResponseWriter, r *http.Request)
	// GetGithubConnection The GitHub token of the workspace (DEC-019). The token itself is never returned.
	// (GET /admin/github)
	GetGithubConnection(w http.ResponseWriter, r *http.Request)
	// SetGithubConnection Set the fine-grained personal access token that reads repos and opens pull requests.
	// (PUT /admin/github)
	SetGithubConnection(w http.ResponseWriter, r *http.Request)
	// ListInvites List invite links, newest first (REQ-081).
	// (GET /admin/invites)
	ListInvites(w http.ResponseWriter, r *http.Request)
	// CreateInvite Make a single-use invite link with a role (REQ-081). The URL appears one time.
	// (POST /admin/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request)
	// RevokeInvite Revoke an unused invite link.
	// (POST /admin/invites/{inviteId}/revoke)
	RevokeInvite(w http.ResponseWriter, r *http.Request, inviteId openapi_types.UUID)
	// ListMCPConnections List the MCP connections (REQ-112).
	// (GET /admin/mcp)
	ListMCPConnections(w http.ResponseWriter, r *http.Request)
	// CreateMCPConnection Add an MCP connection.
	// (POST /admin/mcp)
	CreateMCPConnection(w http.ResponseWriter, r *http.Request)
	// DeleteMCPConnection Delete an MCP connection.
	// (DELETE /admin/mcp/{connectionId})
	DeleteMCPConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// UpdateMCPConnection Change an MCP connection. Leave the secret out to keep the stored one.
	// (PUT /admin/mcp/{connectionId})
	UpdateMCPConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ListMCPTools Connect and list the server's tools, to choose the allowlist.
	// (GET /admin/mcp/{connectionId}/tools)
	ListMCPTools(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ListPresets List the agent CLI presets and whether each CLI is installed (REQ-102).
	// (GET /admin/presets)
	ListPresets(w http.ResponseWriter, r *http.Request)
	// CreateResetLink Make a one-time password reset link for a user (REQ-082). The URL appears one time.
	// (POST /admin/reset-links)
	CreateResetLink(w http.ResponseWriter, r *http.Request)
	// ListRoles List the roles and their backend and model (REQ-101).
	// (GET /admin/roles)
	ListRoles(w http.ResponseWriter, r *http.Request)
	// UnassignRole Remove a role's assignment.
	// (DELETE /admin/roles/{role})
	UnassignRole(w http.ResponseWriter, r *http.Request, role RoleName)
	// AssignRole Assign a backend and model to a role.
	// (PUT /admin/roles/{role})
	AssignRole(w http.ResponseWriter, r *http.Request, role RoleName)
	// GetSettings The workspace settings (REQ-009, REQ-081, REQ-105).
	// (GET /admin/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// SetSettings Change the workspace settings.
	// (PUT /admin/settings)
	SetSettings(w http.ResponseWriter, r *http.Request)
	// ListBundles List bundles, and the folders that look like bundles but are not valid.
	// (GET /bundles)
	ListBundles(w http.ResponseWriter, r *http.Request, params ListBundlesParams)
	// CreateBundle Create a bundle from a profile's template (REQ-016).
	// (POST /bundles)
	CreateBundle(w http.ResponseWriter, r *http.Request)
	// ImportBundle Import a bundle from a .md file, a .zip file, or pasted markdown.
	// (POST /bundles/import)
	ImportBundle(w http.ResponseWriter, r *http.Request)
	// GetBundle Get one bundle.
	// (GET /bundles/{bundleId})
	GetBundle(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// GetBundleAccess Who can see the bundle, and its share link state (REQ-084, REQ-085).
	// (GET /bundles/{bundleId}/access)
	GetBundleAccess(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// AdoptFrontmatter Write the type and the size that the review used into the main doc's frontmatter (REQ-135).
	// (POST /bundles/{bundleId}/adopt)
	AdoptFrontmatter(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ApproveBundle Approve the current version (REQ-076). The author cannot approve. Approval needs a current Build Ready verdict.
	// (POST /bundles/{bundleId}/approve)
	ApproveBundle(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListAssumptions List the sentences of the current main doc that start with "Assumption:" (REQ-033).
	// (GET /bundles/{bundleId}/assumptions)
	ListAssumptions(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// DiffVersions Compare two versions of a bundle, by file and by section of the main doc (REQ-006).
	// (GET /bundles/{bundleId}/diff)
	DiffVersions(w http.ResponseWriter, r *http.Request, bundleId BundleId, params DiffVersionsParams)
	// SummarizeDiff Summarize what changed in meaning between two versions, and the change in findings (REQ-007).
	// (POST /bundles/{bundleId}/diff/summary)
	SummarizeDiff(w http.ResponseWriter, r *http.Request, bundleId BundleId, params SummarizeDiffParams)
	// DiscardDraft Drop the draft of a GitHub bundle. The version from GitHub becomes current again.
	// (POST /bundles/{bundleId}/draft/discard)
	DiscardDraft(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ExportBundle Download a bundle version as a .zip file, or the current version as a self-contained HTML report with the verdict (REQ-008).
	// (GET /bundles/{bundleId}/export)
	ExportBundle(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ExportBundleParams)
	// DeleteFile Delete a file. Creates a version (REQ-005).
	// (DELETE /bundles/{bundleId}/files)
	DeleteFile(w http.ResponseWriter, r *http.Request, bundleId BundleId, params DeleteFileParams)
	// ListFiles List the files of a bundle version. The default is the current version.
	// (GET /bundles/{bundleId}/files)
	ListFiles(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ListFilesParams)
	// GetFileContent Get the bytes of one file in a bundle version. The default is the current version.
	// (GET /bundles/{bundleId}/files/content)
	GetFileContent(w http.ResponseWriter, r *http.Request, bundleId BundleId, params GetFileContentParams)
	// PutFileContent Create or replace a file. Creates a version when the content changed (REQ-005).
	// (PUT /bundles/{bundleId}/files/content)
	PutFileContent(w http.ResponseWriter, r *http.Request, bundleId BundleId, params PutFileContentParams)
	// RenameFile Rename or move a file inside the bundle. Creates a version (REQ-005).
	// (POST /bundles/{bundleId}/files/rename)
	RenameFile(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// PublishBundle Publish the draft of a GitHub bundle as a branch, a commit, and a pull request (REQ-123).
	// (POST /bundles/{bundleId}/publish)
	PublishBundle(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// RequestReview Ask for a review and assign reviewers (REQ-090). A draft moves to in review.
	// (POST /bundles/{bundleId}/review-request)
	RequestReview(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListRuns List the review runs of a bundle, newest first.
	// (GET /bundles/{bundleId}/runs)
	ListRuns(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ListRunsParams)
	// StartRun Start a full review of the current version (REQ-020). Lint runs on its own on every save.
	// (POST /bundles/{bundleId}/runs)
	StartRun(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// EstimateRun Estimate the tokens and cost of a full review before it starts (REQ-104).
	// (GET /bundles/{bundleId}/runs/estimate)
	EstimateRun(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// RevokeShareLink Revoke the share link (REQ-085).
	// (DELETE /bundles/{bundleId}/share)
	RevokeShareLink(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// CreateShareLink Make a new share link (REQ-085). It replaces the old one and sets link visibility. The URL appears one time.
	// (POST /bundles/{bundleId}/share)
	CreateShareLink(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// GetBundleStatus The review status of a bundle (§9.5).
	// (GET /bundles/{bundleId}/status)
	GetBundleStatus(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListBundleThreads List the threads of a bundle, open first (REQ-087).
	// (GET /bundles/{bundleId}/threads)
	ListBundleThreads(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// OpenBundleThread Open a thread on a bundle, anchored to text, a section, or a finding (REQ-087). A guest opens threads for humans only.
	// (POST /bundles/{bundleId}/threads)
	OpenBundleThread(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// GetTour The ordered points of the bundle's current review that need a human decision (SDD §13.3).
	// (GET /bundles/{bundleId}/tour)
	GetTour(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// GetTrace The bundle's links, its traceability matrices, and suggested trace IDs (REQ-050, REQ-052, REQ-058).
	// (GET /bundles/{bundleId}/trace)
	GetTrace(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// AddTraceIds Insert suggested trace IDs into the main doc (REQ-052). Speccy changes the doc only on this request.
	// (POST /bundles/{bundleId}/trace/ids)
	AddTraceIds(w http.ResponseWriter, r *http.Request, bundleId BundleId, params AddTraceIdsParams)
	// ListVersions List the versions of a bundle, newest first.
	// (GET /bundles/{bundleId}/versions)
	ListVersions(w http.ResponseWriter, r *http.Request, bundleId BundleId, params ListVersionsParams)
	// SetVisibility Set the visibility of the bundle (REQ-084). Leaving link visibility revokes the share link.
	// (PUT /bundles/{bundleId}/visibility)
	SetVisibility(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListWaivers List the waivers of a bundle (REQ-072 to REQ-074).
	// (GET /bundles/{bundleId}/waivers)
	ListWaivers(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// RequestWaiver Request a waiver for one finding, with a reason of at least 20 characters (REQ-072).
	// (POST /bundles/{bundleId}/waivers)
	RequestWaiver(w http.ResponseWriter, r *http.Request, bundleId BundleId)
	// ListGithubSources The GitHub repos, branches, and folders that Speccy reads bundles from (REQ-123).
	// (GET /github/sources)
	ListGithubSources(w http.ResponseWriter, r *http.Request)
	// AddGithubSource Read the bundles of a folder on a branch of a repo, and keep them in step (REQ-123).
	// (POST /github/sources)
	AddGithubSource(w http.ResponseWriter, r *http.Request)
	// DeleteGithubSource Stop reading a source. Its bundles are archived; their reviews and threads stay.
	// (DELETE /github/sources/{sourceId})
	DeleteGithubSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// SyncGithubSource Read the source's branch now.
	// (POST /github/sources/{sourceId}/sync)
	SyncGithubSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// GetInbox The caller's inbox (REQ-091).
	// (GET /inbox)
	GetInbox(w http.ResponseWriter, r *http.Request)
	// MarkInboxSeen Mark the inbox as read up to now.
	// (POST /inbox/seen)
	MarkInboxSeen(w http.ResponseWriter, r *http.Request)
	// GetInsights The metrics of SDD §8.9, per profile (REQ-092). Maintainers and admins.
	// (GET /insights)
	GetInsights(w http.ResponseWriter, r *http.Request)
	// GetMe Who the caller is (SDD §3). Anonymous callers get signed_in false.
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetMeta Get the server version and mode.
	// (GET /meta)
	GetMeta(w http.ResponseWriter, r *http.Request)
	// ListPeople The members of the workspace, for reviewers and mentions. Empty in local mode.
	// (GET /people)
	ListPeople(w http.ResponseWriter, r *http.Request)
	// ListProfiles List the profiles, with their current versions.
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// CreateProfile Create a profile for a new doc type. Admins only.
	// (POST /profiles)
	CreateProfile(w http.ResponseWriter, r *http.Request)
	// GetProfile A profile with its YAML, template, versions, and maintainers (REQ-013).
	// (GET /profiles/{key})
	GetProfile(w http.ResponseWriter, r *http.Request, key ProfileKey)
	// UpdateProfile Save a profile as a new version (REQ-012, REQ-013). Maintainers of the profile and admins.
	// (PUT /profiles/{key})
	UpdateProfile(w http.ResponseWriter, r *http.Request, key ProfileKey)
	// SetMaintainers Set the maintainers of a profile. Admins only.
	// (PUT /profiles/{key}/maintainers)
	SetMaintainers(w http.ResponseWriter, r *http.Request, key ProfileKey)
	// ListProfileThreads The suggestions for a profile, as threads on its checks (REQ-015).
	// (GET /profiles/{key}/threads)
	ListProfileThreads(w http.ResponseWriter, r *http.Request, key ProfileKey)
	// OpenProfileThread Suggest a change to a check, the template, or a limit (REQ-015).
	// (POST /profiles/{key}/threads)
	OpenProfileThread(w http.ResponseWriter, r *http.Request, key ProfileKey)
	// RenderMarkdown Render markdown to HTML. Each block carries its source position (DEC-017).
	// (POST /render)
	RenderMarkdown(w http.ResponseWriter, r *http.Request)
	// ReviewContent Review bundle files that are not saved on the server (SDD §12.2 --server, REQ-111 review_content). The server keeps the files and the result for 90 days for the report (SDD §12.4); it changes no bundle.
	// (POST /reviews)
	ReviewContent(w http.ResponseWriter, r *http.Request)
	// GetContentReviewReport The self-contained HTML report of a review from POST /reviews (SDD §12.4).
	// (GET /reviews/{reviewId}/report)
	GetContentReviewReport(w http.ResponseWriter, r *http.Request, reviewId openapi_types.UUID)
	// GetRun Get one review run and its verdict.
	// (GET /runs/{runId})
	GetRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// ListClaims List a run's factual claims and their labels (REQ-031).
	// (GET /runs/{runId}/claims)
	ListClaims(w http.ResponseWriter, r *http.Request, runId RunId)
	// RunEvents Follow a run's progress by stage, as server-sent events (REQ-026).
	// (GET /runs/{runId}/events)
	RunEvents(w http.ResponseWriter, r *http.Request, runId RunId)
	// ListFindings List the findings of a run, in document order.
	// (GET /runs/{runId}/findings)
	ListFindings(w http.ResponseWriter, r *http.Request, runId RunId)
	// SuggestFix Ask the AI for a patch that fixes one finding (REQ-025). The doc does not change.
	// (POST /runs/{runId}/findings/{findingId}/fix)
	SuggestFix(w http.ResponseWriter, r *http.Request, runId RunId, findingId FindingId)
	// AcceptFix Apply the finding's suggested patch to the current version as a new version (REQ-025). Speccy changes the doc only on this request.
	// (POST /runs/{runId}/findings/{findingId}/fix/accept)
	AcceptFix(w http.ResponseWriter, r *http.Request, runId RunId, findingId FindingId)
	// ListQuestions List a run's build questions, reader answers, and results (REQ-040 to REQ-046).
	// (GET /runs/{runId}/questions)
	ListQuestions(w http.ResponseWriter, r *http.Request, runId RunId)
	// GetRunReport The run report (SDD §13.1): stage timings, reader diversity, and findings by category.
	// (GET /runs/{runId}/report)
	GetRunReport(w http.ResponseWriter, r *http.Request, runId RunId)
	// GetShare Look up a share link (REQ-085). A revoked or expired link is not found.
	// (GET /share/{token})
	GetShare(w http.ResponseWriter, r *http.Request, token string)
	// JoinShare Enter a share link as a guest with a display name (REQ-086). Sets the guest cookie.
	// (POST /share/{token})
	JoinShare(w http.ResponseWriter, r *http.Request, token string)
	// GetThread A thread with its messages.
	// (GET /threads/{threadId})
	GetThread(w http.ResponseWriter, r *http.Request, threadId ThreadId)
	// SetThreadBlocking Mark the thread blocking or not. An open blocking thread prevents Build Ready (REQ-089).
	// (PUT /threads/{threadId}/blocking)
	SetThreadBlocking(w http.ResponseWriter, r *http.Request, threadId ThreadId)
	// MarkDecision Mark a message as the thread's decision. A later decision is recorded as a reversal (REQ-089).
	// (POST /threads/{threadId}/decision)
	MarkDecision(w http.ResponseWriter, r *http.Request, threadId ThreadId)
	// PostMessage Post a message. In a thread for the AI, the AI answers with sources (REQ-088).
	// (POST /threads/{threadId}/messages)
	PostMessage(w http.ResponseWriter, r *http.Request, threadId ThreadId)
	// SetThreadStatus Resolve or reopen the thread.
	// (PUT /threads/{threadId}/status)
	SetThreadStatus(w http.ResponseWriter, r *http.Request, threadId ThreadId)
	// ApproveWaiver Approve a waiver under the profile's policy (REQ-073, §9.1). A final approval writes it to the frontmatter (DEC-009).
	// (POST /waivers/{waiverId}/approve)
	ApproveWaiver(w http.ResponseWriter, r *http.Request, waiverId WaiverId)
	// RejectWaiver Reject a waiver, with a decision reason the requester reads.
	// (POST /waivers/{waiverId}/reject)
	RejectWaiver(w http.ResponseWriter, r *http.Request, waiverId WaiverId)
}

